    IDLE:
        motorUp   := FALSE;
        motorDown := FALSE;
        errorFlag := FALSE;
        IF openRising AND NOT openLimit THEN
            state := OPENING;
            motorUp := TRUE;
        ELSIF closeRising AND NOT closeLimit THEN
            state := CLOSING;
            motorDown := TRUE;
