        motorUp   := TRUE;
        motorDown := FALSE;
        IF openLimit THEN
            state := IDLE;
            motorUp := FALSE;
        ELSIF obstacle THEN
            state := FAULT;
            motorUp := FALSE;
            errorFlag := TRUE;
