        motorUp   := FALSE;
        motorDown := FALSE;
        errorFlag := TRUE;
        IF bothRising AND NOT obstacle THEN
            state := IDLE;
            errorFlag := FALSE;
        END_IF
END_CASE

END_FUNCTION_BLOCK

